let living=localRead('chatState',null)?.living||{guests:[],avatars:{},events:[],jobs:[]},livingChatBusy=false,livingChatController=null,livingBubbles={},livingDressing='me';
living={guests:[],avatars:{},events:[],jobs:[],...living};
function livingCommit(nextWallet=wallet,nextLiving=living,nextHome=homeland){const old=[wallet,living,homeland];try{wallet=nextWallet;living=nextLiving;homeland=nextHome;persist()}catch(e){[wallet,living,homeland]=old;throw e}}
function livingEvent(state,content,audience=state.guests,speaker='system',privateEvent=false){if(state.events.length>=10000)throw Error('家园经历已达 10000 条，请先导出备份归档');return PalaisLiving.event(state,{id:crypto.randomUUID(),at:Date.now(),content,audience,speaker,private:privateEvent})}
function moneyPrompt(id){const a=PalaisLiving.account(wallet,id),card=wallet.kinCards?.[id];return '\n【虚拟财务】你自己的独立资产为 ¥'+PalaisWallet.money(a.balance)+'。用户零钱与其他角色资产都不属于你。红包单个至多 200 元；转账无产品金额上限，但不能超出你的资产。可以用 [[红包|金额|祝福]] 或 [[转账|金额|留言]]，均为虚拟金额。你可以根据自己的人设和关系主动提供亲属卡，或在用户提出时选择答应、拒绝、商量额度。提供时用 [[亲属卡|每月额度|留言]]，每月自然月刷新，实际消费由你付款；不必每次都开通，不能假装已经开通，用户需要接受。'+(card?'你已提供月额度 ¥'+PalaisWallet.money(card.limit)+' 的亲属卡。':'目前没有给用户的亲属卡。')}
function prepareLivingReply(text){const c=PalaisLiving.control(text),p=parseChatReply(c.text);if(c.kin){try{PalaisWallet.cents(c.kin.amount);p.kin=c.kin}catch{p.content+='（亲属卡额度无效，未创建）'}}return p}
function reserveRoleMoney(message){if(!message.card)return wallet;const c=message.card;return PalaisLiving.send(wallet,{id:message.id,peerId:message.sender,type:c.type,note:c.note,at:message.createdAt,direction:'role'},PalaisWallet.cents(c.amount))}
function outgoingMoney(r,user){const peerId=r.members?user.card.recipient:r.id;if(!roles.some(x=>x.id===peerId)||r.members&&!r.members.includes(peerId))throw Error('请选择一位有效的收款角色');return PalaisLiving.send(wallet,{id:user.id,peerId,peer:roles.find(x=>x.id===peerId).name,type:user.card.type,note:user.card.note,at:user.createdAt,direction:'user'},PalaisWallet.cents(user.card.amount))}
function sendGift(r){if(busy||livingChatBusy){toast('等当前回复完成后再发送');return}const d=panel(`<form id="giftForm" class="living-form"><h2>红包 / 转账</h2><div class="notice">可用零钱 ¥ ${PalaisWallet.money(wallet.balance)}</div><label>选择发送方式<select name="kind"><option value="redpacket">红包 · 最多 200 元</option><option value="transfer">转账 · 按可用余额支付</option></select></label>${r.members?`<label>收款角色<select name="recipient">${r.members.map(id=>roles.find(x=>x.id===id)).filter(Boolean).map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.name)}</option>`).join('')}</select></label>`:''}<label>金额（元）<input name="amount" inputmode="decimal" required placeholder="0.00"></label><label>留言<input name="note" maxlength="80" placeholder="写一句祝福"></label><p class="daily-caption">红包单个最多 200 元，转账不设产品上限，需在可用余额及可精确记录范围内。全为虚拟资金。</p><div class="actions"><button class="secondary" type="button" id="cancelGift">取消</button><button class="primary">发送</button></div></form>`);$('#cancelGift').onclick=()=>d.close();$('#giftForm').onsubmit=e=>{e.preventDefault();try{const f=e.target,n=PalaisWallet.cents(f.amount.value.trim());if(f.kind.value==='redpacket'&&n>20000)throw Error('单个红包最多 200 元');if(n>wallet.balance)throw Error('零钱余额不足');const card={type:f.kind.value,amount:PalaisWallet.amount(n),note:f.note.value.trim(),status:'sent',recipient:r.members?f.recipient.value:r.id};d.close();sendMessage(r,card.note||'给你发了'+(card.type==='redpacket'?'红包':'转账'),card)}catch(err){toast(err.message)}}}
function receiveGift(r,m){if(!m?.card||m.role!=='assistant'||m.card.status!=='pending')return;const oldStatus=m.card.status;try{const next=PalaisLiving.receive(wallet,{id:m.id,peerId:m.sender||r.id,peer:roles.find(x=>x.id===m.sender)?.name||r.name,type:m.card.type,note:m.card.note,at:Date.now()},PalaisWallet.cents(m.card.amount));m.card.status='received';livingCommit(next);renderConversation();toast('已收入零钱 ¥'+m.card.amount)}catch(e){m.card.status=oldStatus;toast(e.message)}}
function kinHTML(m){return m.kin?`<button class="kin-offer" data-kin-offer="${escapeHtml(m.id)}" ${m.kin.status==='accepted'?'disabled':''}>♡ 亲属卡 · 每月 ¥${escapeHtml(m.kin.amount)}<small>${escapeHtml(m.kin.note||'一起照顾日常的小开销')} · ${m.kin.status==='accepted'?'已接受':'点击接受'}</small></button>`:''}
function bindKinOffers(r,history){document.querySelectorAll('[data-kin-offer]').forEach(b=>b.onclick=()=>{const m=history.find(x=>x.id===b.dataset.kinOffer);if(!m?.kin||m.kin.status==='accepted')return;const status=m.kin.status;try{const next=PalaisLiving.kin(wallet,{id:m.id,roleId:m.sender,note:m.kin.note,at:Date.now()},PalaisWallet.cents(m.kin.amount));m.kin.status='accepted';livingCommit(next);renderConversation();toast('已接受亲属卡，可在家园商店选择付款')}catch(e){m.kin.status=status;toast(e.message)}})}
function renderWallet(){const cards=Object.values(wallet.kinCards||{});screen.innerHTML=`<section class="view">${wxHeading('零钱与亲属卡','MY VIRTUAL WALLET')}<div class="wallet-hero"><span>自己的零钱</span><strong>¥ ${PalaisWallet.money(wallet.balance)}</strong></div><div class="living-wallet-tabs"><button id="walletShop">去购物</button><button id="walletRoles">角色独立资产</button></div><h3>我的亲属卡</h3>${cards.map(c=>`<div class="kin-card"><b>${escapeHtml(roles.find(r=>r.id===c.roleId)?.name||'角色')}的亲属卡</b><strong>¥ ${PalaisWallet.money(PalaisLiving.available(wallet,c.roleId))}</strong><p>当前可用 · 月额度 ¥${PalaisWallet.money(c.limit)}<br>本月已用 ¥${PalaisWallet.money(c.month===PalaisLiving.month(Date.now())?c.spent:0)} · 自然月重置<br>可用金额同时受出资角色余额约束。</p></div>`).join('')||'<p class="daily-empty">还没有亲属卡，可以在聊天中向角色提起。</p>'}<h3>收支明细</h3>${wallet.ledger.slice(-100).reverse().map(x=>`<div class="daily-row"><div class="daily-detail"><b>${escapeHtml(x.type==='home'?'家园日常':x.type==='shopping'?'购物':x.type==='redpacket'?'红包':'转账')} · ${escapeHtml(x.peer||x.note||'零钱')}</b><small>${new Date(x.createdAt).toLocaleString('zh-CN')}</small></div><b>${x.delta<0?'−':'+'}${PalaisWallet.money(Math.abs(x.delta))}</b></div>`).join('')}<button class="secondary full" id="backWxMe">返回微信设置</button><p class="daily-caption">角色账户、用户余额和亲属卡额度分别记录，购物与卡片均为虚拟资金。亲属卡开通不直接转入零钱；每次购物扣出资角色资产。</p></section>`;bindWxHome();$('#walletShop').onclick=()=>go('shop');$('#walletRoles').onclick=openRoleAccounts;$('#backWxMe').onclick=renderWxMe}
function openRoleAccounts(){const d=panel(`<h2>角色独立资产</h2><p class="daily-caption">每位角色初始虚拟资产独立为 ¥10,000，可按人设手动设定。不会读取其他角色的账户。</p>${roles.map(r=>`<div class="daily-row"><div class="daily-detail"><b>${escapeHtml(r.name)}</b><small>¥${PalaisWallet.money(PalaisLiving.account(wallet,r.id).balance)}</small></div><button data-role-assets="${escapeHtml(r.id)}">按人设设定</button></div>`).join('')}<button class="secondary full" id="closeRoleAccounts">完成</button>`);$('#closeRoleAccounts').onclick=()=>d.close();d.querySelectorAll('[data-role-assets]').forEach(b=>b.onclick=()=>{const id=b.dataset.roleAssets;d.close();const f=panel(`<form class="living-form" id="roleAssetsForm"><h2>设定虚拟资产</h2><label>金额（元）<input name="amount" inputmode="decimal" required value="${PalaisWallet.amount(PalaisLiving.account(wallet,id).balance)}"></label><p class="daily-caption">用于角色扮演的人设资产设定，会保留变更记录，不改变用户余额。</p><div class="actions"><button type="button" class="secondary" id="cancelAssets">取消</button><button class="primary">保存</button></div></form>`);$('#cancelAssets').onclick=()=>f.close();$('#roleAssetsForm').onsubmit=e=>{e.preventDefault();try{const n=PalaisLiving.normalize(wallet),amount=e.target.amount.value.trim(),v=/^0(?:\.0{1,2})?$/.test(amount)?0:PalaisWallet.cents(amount),a=PalaisLiving.clone(PalaisLiving.account(n,id));a.ledger.push({id:crypto.randomUUID(),type:'人设调整',delta:v-a.balance,balance:v,at:Date.now()});a.balance=v;n.accounts[id]=a;livingCommit(n);f.close();openRoleAccounts()}catch(err){toast(err.message)}}})}
function paymentOptions(){return '<option value="self">自己的零钱 · ¥'+PalaisWallet.money(wallet.balance)+'</option>'+Object.values(wallet.kinCards||{}).filter(c=>roles.some(r=>r.id===c.roleId)).map(c=>`<option value="${escapeHtml(c.roleId)}">${escapeHtml(roles.find(r=>r.id===c.roleId).name)}亲属卡 · 可用 ¥${PalaisWallet.money(PalaisLiving.available(wallet,c.roleId))}</option>`).join('')}
let shopCategory='全部',shopQuery='',shopShelf='goods';
function renderShop(){
 const entries=Object.entries(PalaisLiving.catalog),categories=['全部',...new Set(entries.map(([,i])=>i.category))];
 screen.innerHTML=`<section class="view shop20">${title('购物','LITTLE EVERYDAY SHOP')}<button class="text-button" data-go="home">‹ 回到桌面</button><div class="shop20-hero"><small>为日常添一点喜欢</small><h2>今天，想带什么回家？</h2><p>零钱 ¥${PalaisWallet.money(wallet.balance)} · 支持亲属卡</p></div><div class="shop20-tabs"><button data-shelf="goods">逛货架</button><button data-shelf="bag">我的物品</button><button data-shelf="orders">购买记录</button></div><input id="shopSearch" aria-label="搜索商品" placeholder="搜索食材、饮料、日用品…" value="${escapeHtml(shopQuery)}"><div class="shop20-categories">${categories.map(c=>`<button data-category="${c}" class="${c===shopCategory?'selected':''}">${c}</button>`).join('')}</div><div id="shopResults"></div><button class="secondary full" id="shopKitchen">去家园厨房 · ${Object.keys(PalaisLiving.recipes).length} 道菜谱</button><p class="daily-caption">应用内虚拟商品，购买后放入物品库存；食材可在厨房做饭。日用品暂不支持摆放或消耗，不包含实物配送。</p></section>`;
 $('#shopSearch').oninput=e=>{shopQuery=e.target.value;shopDrawResults()};document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{shopCategory=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('selected',x===b));shopDrawResults()});document.querySelectorAll('[data-shelf]').forEach(b=>b.onclick=()=>{shopShelf=b.dataset.shelf;shopDrawResults()});$('#shopKitchen').onclick=()=>{go('homeland');openLivingKitchen()};document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));shopDrawResults();
}
function shopDrawResults(){
 document.querySelectorAll('[data-shelf]').forEach(b=>b.classList.toggle('selected',b.dataset.shelf===shopShelf));
 const rows=Object.entries(PalaisLiving.catalog).filter(([id,i])=>(shopCategory==='全部'||i.category===shopCategory)&&i.name.includes(shopQuery.trim())&&(shopShelf!=='bag'||(wallet.inventory?.[id]||0)>0));
 const results=$('#shopResults');if(shopShelf==='orders'){const orders=(wallet.orders||[]).filter(o=>rows.some(([id])=>id===o.item)).slice().reverse();results.innerHTML=orders.map(o=>{const i=PalaisLiving.catalog[o.item];return `<div class="shop20-order"><span>${i.icon}</span><div><b>${i.name} × ${o.quantity}</b><small>${new Date(o.at).toLocaleString('zh-CN')} · ${o.pay==='self'?'零钱':'亲属卡'}</small></div><b>¥${PalaisWallet.money(o.total)}</b></div>`}).join('')||'<p class="daily-empty">这里还没有购买记录</p>';return}
 results.innerHTML=`<p class="daily-caption">${shopShelf==='bag'?'已拥有':'在售'} ${rows.length} 种商品</p><div class="living-catalog">${rows.map(([id,i])=>`<div class="living-item"><span>${i.icon}</span><small>${i.category}</small><b>${i.name}</b><small>¥${PalaisWallet.money(i.price)} · 已有 ${wallet.inventory?.[id]||0}</small><button class="primary" data-buy-item="${id}">${shopShelf==='bag'?'再买一些':'购买'}</button></div>`).join('')}</div>${rows.length?'':'<p class="daily-empty">没有找到商品，换个分类或关键词吧</p>'}`;results.querySelectorAll('[data-buy-item]').forEach(b=>b.onclick=()=>openBuyItem(b.dataset.buyItem));
}
function openBuyItem(id){const item=PalaisLiving.catalog[id],d=panel(`<form class="living-form" id="buyItemForm"><h2>${item.icon} ${item.name}</h2><p>单价 ¥${PalaisWallet.money(item.price)}</p><label>数量<input name="quantity" type="number" min="1" max="99" required value="1"></label><label>选择付款账户<select name="pay">${paymentOptions()}</select></label><p class="daily-caption" id="buyTotal"></p><div class="actions"><button type="button" class="secondary" id="cancelBuy">取消</button><button class="primary">确认购买</button></div></form>`);const f=$('#buyItemForm'),show=()=>$('#buyTotal').textContent='合计 ¥'+PalaisWallet.money(item.price*Number(f.quantity.value||0));f.quantity.oninput=show;show();$('#cancelBuy').onclick=()=>d.close();f.onsubmit=e=>{e.preventDefault();try{const next=PalaisLiving.purchase(wallet,{id:crypto.randomUUID(),item:id,quantity:Number(f.quantity.value),pay:f.pay.value,at:Date.now()});livingCommit(next);d.close();toast('购买成功，商品已放入我的物品');if(tab==='shop')renderShop()}catch(err){toast(err.message)}}}
